#!/usr/bin/env node
/**
 * fork-transcript.mjs — the Slice C transcript harness.
 *
 * Runs the four scripted scenarios (src/fork/scenarios.ts) through the
 * turn loop and writes docs/fork/transcript-sample.md with the full
 * transcript AND the per-turn trace (parse summary, classifications,
 * pronoun resolutions, cycle path / derivation used, decline reasons).
 * Real output only — the file is regenerated by running the code.
 *
 * Run: npm run fork:transcript
 */
import { writeFileSync } from "node:fs";
import { newSession } from "../dist/src/fork/session.js";
import { processTurn } from "../dist/src/fork/turn.js";
import { SCENARIOS } from "../dist/src/fork/scenarios.js";

const lines = [];
lines.push("# Transcript sample — Slice C turn loop (generated)");
lines.push("");
lines.push("Generated by `npm run fork:transcript` from the four scripted");
lines.push("scenarios in `src/fork/scenarios.ts`, run through the real turn");
lines.push("loop (`src/fork/turn.ts`). Each bot turn shows its trace: the");
lines.push("parse summary, the classifications the join produced, pronoun");
lines.push("resolutions, and the cycle path or derivation the reply was");
lines.push("steered by. The ontology is never named in a reply — the trace");
lines.push("is internal and may name the machinery.");
lines.push("");

for (const scenario of SCENARIOS) {
  const session = newSession();
  lines.push(`## ${scenario.title}`);
  lines.push("");
  for (const input of scenario.turns) {
    const { reply, trace } = processTurn(session, input);
    lines.push(`**You:** ${input}`);
    lines.push("");
    lines.push(`**Bot:** ${reply}`);
    lines.push("");
    lines.push("```text");
    lines.push(`trace turn ${trace.turn}: ${trace.parseSummary}`);
    if (trace.classifications.length) {
      lines.push(`  classifications: ${trace.classifications.map((c) => `${c.concept} -> ${c.element} @${c.confidence} (${c.provenance})`).join("; ")}`);
    }
    if (trace.resolutions.length) {
      lines.push(`  resolutions: ${trace.resolutions.map((r) => `'${r.pronoun}' -> ${r.resolvedTo}`).join("; ")}`);
    }
    if (trace.cyclePath) lines.push(`  cycle path: ${trace.cyclePath}`);
    if (trace.derivationPath) lines.push(`  derivation: ${trace.derivationPath}`);
    if (trace.steeringNote) lines.push(`  steering: ${trace.steeringNote}`);
    if (trace.declineReason) lines.push(`  decline: ${trace.declineReason}`);
    lines.push("```");
    lines.push("");
  }
}

const out = new URL("../docs/fork/transcript-sample.md", import.meta.url);
writeFileSync(out, lines.join("\n"));
console.log(`wrote docs/fork/transcript-sample.md (${SCENARIOS.length} scenarios, ${SCENARIOS.reduce((n, s) => n + s.turns.length, 0)} turns)`);
